def maximum_sum_queries_brute(nums1, nums2, queries):
    n = len(nums1)
    res = []
    for x, y in queries:
        best = -1
        for i in range(n):                                    # scan every index, every query
            if nums1[i] >= x and nums2[i] >= y:
                best = max(best, nums1[i] + nums2[i])
        res.append(best)
    return res

