import java.util.*;

public class Main {
    static int[] maximumSumQueries(int[] nums1, int[] nums2, int[][] queries) {
        int n = nums1.length;
        Integer[] idxs = new Integer[n];
        for (int i = 0; i < n; i++) idxs[i] = i;
        Arrays.sort(idxs, (a, b) -> nums1[b] - nums1[a]);
        int qn = queries.length;
        Integer[] qOrder = new Integer[qn];
        for (int i = 0; i < qn; i++) qOrder[i] = i;
        Arrays.sort(qOrder, (a, b) -> queries[b][0] - queries[a][0]);

        int[] stackY = new int[n], stackSum = new int[n];
        int top = -1;
        int[] res = new int[qn];
        Arrays.fill(res, -1);
        int ptr = 0;
        for (int qi : qOrder) {
            int x = queries[qi][0], y = queries[qi][1];
            while (ptr < n && nums1[idxs[ptr]] >= x) {
                int i = idxs[ptr];
                int yy = nums2[i], s = nums1[i] + nums2[i];
                while (top >= 0 && stackSum[top] <= s) top--;      // remove dominated entries
                stackY[++top] = yy;
                stackSum[top] = s;
                ptr++;
            }
            int lo = 0, hi = top, best = -1;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                if (stackY[mid] >= y) { best = stackSum[mid]; hi = mid - 1; } else lo = mid + 1;
            }
            res[qi] = best;
        }
        return res;
    }
}

