#include <bits/stdc++.h>
using namespace std;

vector<int> maximumSumQueries(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
    int n = nums1.size();
    vector<int> idxs(n);
    iota(idxs.begin(), idxs.end(), 0);
    sort(idxs.begin(), idxs.end(), [&](int a, int b) { return nums1[a] > nums1[b]; });
    int qn = queries.size();
    vector<int> qOrder(qn);
    iota(qOrder.begin(), qOrder.end(), 0);
    sort(qOrder.begin(), qOrder.end(), [&](int a, int b) { return queries[a][0] > queries[b][0]; });

    vector<int> stackY, stackSum;      // both strictly increasing bottom to top
    vector<int> res(qn, -1);
    int ptr = 0;
    for (int qi : qOrder) {
        int x = queries[qi][0], y = queries[qi][1];
        while (ptr < n && nums1[idxs[ptr]] >= x) {
            int i = idxs[ptr];
            int yy = nums2[i], s = nums1[i] + nums2[i];
            while (!stackSum.empty() && stackSum.back() <= s) { stackSum.pop_back(); stackY.pop_back(); }
            stackY.push_back(yy);
            stackSum.push_back(s);
            ptr++;
        }
        int lo = 0, hi = (int)stackY.size() - 1, best = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (stackY[mid] >= y) { best = stackSum[mid]; hi = mid - 1; } else lo = mid + 1;
        }
        res[qi] = best;
    }
    return res;
}
